<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import {create} from '../api/batches';import {batchExample} from '../utils/example';import {useAction} from '../hooks/useAction';import Heading from '../components/common/Heading.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const id=ref('demo-package'),text=ref(JSON.stringify(batchExample(),null,2));const pkg=computed(()=>props.data.packages.find(p=>p.id===id.value)||props.data.packages[0]);const batches=computed(()=>props.data.batches.filter(b=>b.package_id===pkg.value?.id));const{busy,error,notice,act}=useAction();const RESULT_LABELS:Record<string,string>={applied:'已入账',revoked:'已撤销',duplicate:'同号同内容·跳过',stale:'旧修订·忽略',conflict:'同号异内容·冲突',superseded:'同批被覆盖'};function fill(){text.value=JSON.stringify(batchExample(pkg.value),null,2)}async function save(){const batch=await create(JSON.parse(text.value));await props.refresh();if(batch.status==='rejected')throw new Error('批次整批未落库：'+batch.error)}</script><template><Heading index="04 / INCREMENTAL BATCHES" title="清单分批补发，按号合并。" detail="任务与依赖按来源、稳定编号与修订号入账：旧修订忽略，同号同内容跳过，同号异内容报冲突；撤销登记墓碑，旧补发不复活。整批先合成最终图再校验，悬空、环或工期错误整批不落库；已冻结情景与已批准报告保持原内容。"/><label class="selector">补发工作包<select aria-label="补发工作包" v-model="id"><option v-for="p in data.packages" :key="p.id" :value="p.id">{{p.name}}</option></select></label><section v-if="canWrite&&pkg" class="form-section"><h2>导入补发批次</h2><p>JSON含package_id、note与tasks/dependencies记录；任务记录带task_id与工期，依赖记录带predecessor/successor，均须source、revision与action（upsert写入 / revoke撤销）。不执行任意公式。</p><form @submit.prevent="act(save,'批次已合并入账，逐条结果见下方台账')"><label>批次JSON<textarea aria-label="批次JSON" v-model="text" rows="9"/></label><div class="actions"><button class="primary" :disabled="busy">校验并合并批次</button><button type="button" @click="fill">填入补发示例</button></div></form><Notice :error="error" :notice="notice"/></section><section><div class="section-rule"><h2>逐批处理台账 · {{batches.length}}批</h2></div><Empty v-if="!batches.length">该工作包尚无补发批次；上方导入第一批后，可在此回看逐条处理结果。</Empty><details v-for="b in batches" :key="b.id"><summary><span class="status" :class="{failed:b.status==='rejected'}">{{b.status==='applied'?'已入账':'未落库'}}</span> {{b.note||'（无备注）'}} · {{b.actor}} · {{b.created_at.slice(0,19).replace('T',' ')}} · 入账{{b.summary.applied||0}} 撤销{{b.summary.revoked||0}} 跳过{{(b.summary.duplicate||0)+(b.summary.stale||0)+(b.summary.superseded||0)}} 冲突{{b.summary.conflict||0}} / 共{{b.summary.total||0}}条</summary><p v-if="b.error" class="notice error">整批未落库：{{b.error}}</p><div class="table-scroll"><table><thead><tr><th>类型</th><th>稳定编号</th><th>来源</th><th>修订</th><th>动作</th><th>结果</th><th>说明</th></tr></thead><tbody><tr v-for="(r,i) in b.results" :key="i"><td>{{r.kind==='task'?'任务':'依赖'}}</td><td>{{r.stable_id}}</td><td>{{r.source}}</td><td>{{r.revision}}</td><td>{{r.action==='upsert'?'写入':'撤销'}}</td><td>{{RESULT_LABELS[r.result]||r.result}}</td><td>{{r.detail}}</td></tr></tbody></table></div></details></section></template>
